import{_ as t,o,c as r,a2 as a}from"./chunks/framework.CFuv5BrO.js";const h=JSON.parse('{"title":"5.2 Correct, forget, and export memory","description":"Wrong memories can be fixed, sensitive information can be forgotten, and all data can be taken away.","frontmatter":{"title":"5.2 Correct, forget, and export memory","description":"Wrong memories can be fixed, sensitive information can be forgotten, and all data can be taken away.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-5/5-2.md","filePath":"en/delivery/stage-5/5-2.md","lastUpdated":1794017073000}'),n={name:"en/delivery/stage-5/5-2.md"};function i(s,e,l,d,c,m){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="_5-2-correct-forget-and-export-memory" tabindex="-1">5.2 Correct, forget, and export memory <a class="header-anchor" href="#_5-2-correct-forget-and-export-memory" aria-label="Permalink to &quot;5.2 Correct, forget, and export memory&quot;">​</a></h1><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><ul><li><strong>Implemented:</strong> Corrections create a new version and keep history; same-topic conflicts require choosing left, right, or merge; forgetting tombstones the current record and redacts matching terms in history, events, and recall audits; export excludes forgotten bodies and <code>secret</code> memory is never recalled.</li><li><strong>Still open:</strong> Cross-device forgetting relies on sync filtering and local-copy boundaries; old copies already exported to external files cannot be remotely erased.</li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Let wrong or outdated memories be corrected, forgotten, and exported, and ensure sensitive information is not used in disallowed contexts.</p><h2 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h2><ol><li>When old and new memories conflict, keep both sources and times, show the conflict, and use the version the user confirms.</li><li>When deleting a memory, also clear summaries, indexes, and related content derived from it so it does not reappear elsewhere.</li><li>Provide a complete memory export in a readable format that the user can take away or migrate.</li><li>Use sensitive information only in explicitly allowed tasks and contexts; one approval does not open it forever.</li><li>External web, email, and file content cannot write memory directly or expand permission; isolate suspicious content first.</li><li>Verify with real correction and forgetting: after the user deletes something, later tasks no longer use it.</li></ol>',7)])])}const p=t(n,[["render",i]]);export{h as __pageData,p as default};
